    // single public test function driving c
    function check_withdraw_all(address payable recipient, uint256 funding) public {
        // fund this test contract so it can forward to c
        require(address(this).balance >= funding, "insufficient test balance");

        // send funding to target contract c so it has a balance to withdraw
        (bool sent, ) = address(c).call{value: funding}("");
        require(sent, "funding failed");

        // record recipient balance before withdraw
        uint256 before = address(recipient).balance;
        // record contract balance before withdraw
        uint256 balBefore = address(c).balance;

        // require caller is owner of c to allow withdraw; we assume this test contract is owner
        // call withdrawAll on c which should transfer the full balance to recipient
        c.withdrawAll(recipient);

        // record after balances
