        uint256 after = address(recipient).balance;

        // General rule: c's balance becomes zero and recipient gained exactly the previous full balance
        assert(balAfter == 0 && after - before == balBefore);
    }

    // allow receiving Ether so tests can fund this contract externally
    receive() external payable {}
}

