    function run(address sender, address payable recipient, uint deposit) public payable {
        require(address(this).balance >= deposit, "insufficient ether for deposit");

        // fund target contract c by sending ether to its fallback
        (bool okFund, ) = address(c).call{value: deposit}("");
        require(okFund, "funding c failed");

        // now attempt withdrawAll from c, calling it as if from `sender`.
        // We simulate calls from arbitrary addresses by using the low-level call
        // with provided sender encoded via msg.sender replacement is impossible in solidity,
        // so instead we require that `sender` is this contract (the only caller),
        // and we drive the distinguishing behavior by calling withdrawAll directly from here.
        // To meet the requirement that the deciding call be a top-level state-changing call
        // on c, we perform it now.

        // Top-level call: this contract calls c.withdrawAll(recipient)
        c.withdrawAll(recipient);

        // Observation: check whether c's balance is zero after the call.
        // On the original contract, only the owner (which is some externally set address) can withdraw.
        // Because this contract is generally not the owner, the call should revert on the original P,
        // leaving c's balance unchanged (i.e., > 0). But the mutant inverted the check, so it would allow
        // non-owner calls to succeed, draining c's balance to zero. We assert that c's balance is nonzero.

        assert(address(c).balance != 0);
