contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // fuzzed params: amount to fund the contract and the recipient address
    function testFuzz_property(uint256 amount, address recipient) public {
        // keep amount within reasonable bounds but allow zero as well
        amount = bound(amount, 0, 1 ether);

        // Ensure recipient can be any address (including this contract or owner)
        // Fund an external account so we can send value into c via recipient or owner
        vm.deal(address(this), amount);

        // Send funds into contract so withdrawAll has a balance to transfer
        if (amount > 0) {
            // we send from this test contract to c
            (bool s,) = address(c).call{value: amount}("");
            require(s);
        }

        // Precondition: caller must be owner (setUp deployed c with owner = address(this))
        // Call withdrawAll with fuzzed recipient
        bool ok;
        try c.withdrawAll(recipient) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for ANY amount and recipient, after a successful call the entire
        // balance of c should be 0 AND the recipient should have received the funds when caller is owner.
        // We express a single assertTrue that the contract balance is zero whenever the call succeeded.
        // The mutant that redirects to owner will still make balance zero, but will not send to the
        // requested recipient when recipient != owner; to detect that, we check that when the
        // recipient is not the owner and there was a positive balance, the call still succeeds but
        // the recipient's balance should increase by amount — this will fail on the mutant for some inputs.

        // We read balances via address(...) .balance which is permitted.
        if (ok) {
            // After successful execution the contract balance must be zero (reference and mutant both satisfy),
            // but additionally the recipient must have received the funds when recipient != owner.
            // We check recipient's balance increase by amount when recipient != owner, which the mutant breaks.

            // To observe recipient's balance change we need its pre-balance. Recompute: send was immediate, so compare.
            // We cannot read historical balance, so instead we structure the test to compute expected recipient balance:
            // If recipient == address(this) (owner) the transfer may go to owner; we must allow that.
            // For the distinguishing case, require recipient != owner and amount > 0, then the correct contract
            // will have forwarded amount to recipient, whereas the mutant will have forwarded to owner.

            if (amount > 0 && recipient != address(this)) {
                // The correct contract will have sent amount to 'recipient', so recipient.balance must be >= amount.
                // Because the fuzzer provided 'recipient' as an EOA (no code) this is observable.
                // assertTrue reading c: we assert that address(c).balance == 0 AND recipient.balance >= amount
                // We combine into one boolean expression and assertTrue on it (single assertion required).
                assertTrue(address(c).balance == 0 && address(recipient).balance >= amount);
            } else {
                // For other cases (amount==0 or recipient==owner) the universal property still holds that contract balance is zero after success.
                assertTrue(address(c).balance == 0);
            }
        } else {
            // If the call reverted, then for the correct contract that should not happen when caller is owner.
            // We assert that the call did not revert (single assertTrue). This will fail for mutated contracts that
            // might behave differently, but primarily we want the recipient mismatch to be caught above.
            assertTrue(ok);
        }
    }
}

